// expect: exit 0
// screen: 0 sqrt(2) = 1.41421356
float root(float x)
{
    float r = x;
    int i;
    for (i = 0; i < 20; i++)
        r = (r + x / r) / 2;
    return r;
}
int main(void)
{
    cls();
    printf("sqrt(2) = %.8f\n", root(2));
    return 0;
}
